import { useLocation, Link } from "react-router-dom";
import { LayoutDashboard, ScanLine, FileText, Puzzle, Settings, Zap, Bot, Sparkles } from "lucide-react";
import { NavLink } from "@/components/NavLink";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarFooter,
  SidebarHeader,
  useSidebar,
} from "@/components/ui/sidebar";
import { Separator } from "@/components/ui/separator";
import { useAuth } from "@/contexts/AuthContext";

const navItems = [
  { title: "Dashboard", url: "/dashboard", icon: LayoutDashboard },
  { title: "New Scan", url: "/scan", icon: ScanLine, highlight: true },
  { title: "AI Agents", url: "/agents", icon: Sparkles, highlight: true },
  { title: "My Reports", url: "/reports", icon: FileText },
  { title: "Integrations", url: "/integrations", icon: Puzzle },
  { title: "Settings", url: "/settings", icon: Settings },
];

export function AppSidebar() {
  const { state } = useSidebar();
  const collapsed = state === "collapsed";
  const location = useLocation();
  const { profile } = useAuth();

  const scansUsed = profile?.scans_used ?? 0;
  const scanLimit = profile?.scan_limit ?? 1; // avoid divide-by-zero
  const usagePercent = Math.round((scansUsed / scanLimit) * 100);

  const isActive = (path: string) =>
    location.pathname === path || location.pathname.startsWith(path + "/");

  return (
    <Sidebar collapsible="icon" className="border-r-0">
      <SidebarHeader className="p-4">
        <Link to="/dashboard" className="flex items-center gap-2.5">
          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary">
            <Bot className="h-4.5 w-4.5 text-primary-foreground" />
          </div>
          {!collapsed && (
            <span className="text-lg font-bold tracking-tight text-sidebar-primary-foreground">
              CROBOT
            </span>
          )}
        </Link>
      </SidebarHeader>

      <SidebarContent className="px-2">
        <SidebarGroup>
          <SidebarGroupContent>
            <SidebarMenu>
              {navItems.map((item) => {
                const active = isActive(item.url);
                return (
                  <SidebarMenuItem key={item.title}>
                    <SidebarMenuButton
                      asChild
                      className={
                        active
                          ? "bg-primary/20 text-white border-l-2 border-primary rounded-none rounded-r-md"
                          : item.highlight
                          ? "text-sidebar-foreground hover:bg-primary/10 hover:text-white"
                          : "text-sidebar-foreground hover:bg-white/5 hover:text-white"
                      }
                    >
                      <NavLink to={item.url} activeClassName="">
                        <item.icon className="h-4 w-4" />
                        {!collapsed && <span>{item.title}</span>}
                      </NavLink>
                    </SidebarMenuButton>
                  </SidebarMenuItem>
                );
              })}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>
      </SidebarContent>

      <SidebarFooter className="p-3">
        {/* Scan usage indicator */}
        {!collapsed && (
          <div className="mb-3 rounded-lg bg-white/5 p-3">
            <div className="flex items-center justify-between mb-1.5">
              <span className="text-[11px] text-sidebar-foreground/70">Scans this month</span>
              <span className="text-[11px] font-medium text-sidebar-primary-foreground">
                {profile ? `${scansUsed}/${scanLimit}` : "—"}
              </span>
            </div>
            <Progress value={profile ? usagePercent : 0} className="h-1.5" />
            <div className="mt-1.5 flex items-center gap-1.5">
              <Badge
                variant="outline"
                className="border-sidebar-border bg-transparent text-[10px] text-sidebar-foreground/70 capitalize px-1.5 py-0"
              >
                {profile?.plan ?? "free"} plan
              </Badge>
            </div>
          </div>
        )}

        <Separator className="mb-3 bg-sidebar-border" />

        {!collapsed ? (
          <Link
            to="/pricing"
            className="flex items-center justify-center gap-2 rounded-lg bg-gradient-to-r from-primary to-primary/80 px-4 py-2.5 text-sm font-medium text-primary-foreground transition-all hover:opacity-90 hover:shadow-lg hover:shadow-primary/20"
          >
            <Zap className="h-4 w-4" />
            Upgrade to Pro
          </Link>
        ) : (
          <Link
            to="/pricing"
            className="flex items-center justify-center rounded-lg bg-primary p-2 text-primary-foreground transition-opacity hover:opacity-90"
          >
            <Zap className="h-4 w-4" />
          </Link>
        )}
      </SidebarFooter>
    </Sidebar>
  );
}

